CREATE OR REPLACE FUNCTION public.lock_subscription_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.profile_id IS NOT NULL THEN PERFORM 1 FROM public.profiles WHERE id=NEW.profile_id FOR UPDATE; IF NEW.status IN ('active','draft','past_due') AND EXISTS(SELECT 1 FROM public.billing_subscriptions WHERE profile_id=NEW.profile_id AND id<>NEW.id AND status IN ('active','draft','past_due')) THEN RAISE EXCEPTION 'Já existe uma assinatura em aberto para esta pessoa'; END IF; IF public.is_subscriber(NEW.profile_id) AND NOT EXISTS(SELECT 1 FROM public.billing_plans WHERE id=NEW.plan_id AND audience='assinante') THEN RAISE EXCEPTION 'Assinante exige plano de público Assinante'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.lock_subscription_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER lock_profile_subscription BEFORE INSERT OR UPDATE ON public.billing_subscriptions FOR EACH ROW EXECUTE FUNCTION public.lock_subscription_profile();
CREATE TABLE public.community_message_claims (context text NOT NULL,reference_id uuid NOT NULL,state text NOT NULL DEFAULT 'sending',claimed_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(context,reference_id));
GRANT ALL ON public.community_message_claims TO service_role;
ALTER TABLE public.community_message_claims ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_messages ON public.community_message_claims FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE OR REPLACE FUNCTION public.claim_community_message(_context text,_reference_id uuid) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE claimed boolean; BEGIN IF _context NOT IN ('community_plan','community_premium','community_request','community_response') THEN RETURN false; END IF; INSERT INTO public.community_message_claims(context,reference_id) VALUES(_context,_reference_id) ON CONFLICT(context,reference_id) DO UPDATE SET state='sending',claimed_at=now(),updated_at=now() WHERE community_message_claims.state='failed' OR (community_message_claims.state='sending' AND community_message_claims.claimed_at<now()-interval '10 minutes') RETURNING true INTO claimed; RETURN coalesce(claimed,false); END $$;
REVOKE ALL ON FUNCTION public.claim_community_message(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_community_message(text,uuid) TO service_role;
DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public.admin_assign_person_plan(uuid,uuid,date,boolean,boolean,uuid,app_role)'::regprocedure); def:=replace(def,'IF _start_date IS NULL', 'IF NOT _as_subscriber AND public.is_subscriber(_profile_id) AND p.audience<>''assinante'' THEN RAISE EXCEPTION ''Revise o papel antes de atribuir plano incompatível''; END IF; IF _start_date IS NULL'); EXECUTE def; END $$;